  action Emit(m: Msg)     action Send(m: Msg)       action Resend(m: Msg)
  action LoseReq(m: Msg)  action DeliverReq(m: Msg) action LoseAck(m: Msg)
  action DeliverAck(m: Msg)  action Archive()

