import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../build/host.gen.ts';

const views = async (h: any) => Promise.all(['n0', 'n1', 'n2'].map((n) => h.node(n)));

test('initial state and unknown ids', async () => {
  const h = await createHost();
  assert.deepEqual(await h.node('n0'), { role: 'follower', term: 0, votedFor: null });
  assert.equal(await h.node('n9'), null);
  assert.equal((await h.timeout('n9')).ok, false);
  assert.deepEqual(await h.inFlight(), []);
  await h.__dispose();
});

test('single election', async () => {
  const h = await createHost();
  assert.deepEqual(await h.timeout('n0'), { ok: true });
  assert.deepEqual(await h.node('n0'), { role: 'candidate', term: 1, votedFor: 'n0' });
  const msgs = await h.inFlight();
  assert.equal(msgs.length, 2);
  for (const m of msgs) {
    assert.equal(m.from, 'n0');
    assert.equal(m.action, 'RequestVote');
    assert.deepEqual(m.data, { from: 'n0', term: 1 });
  }
  assert.equal((await h.timeout('n0')).ok, false);
  await h.deliver(msgs[0].id);
  assert.deepEqual(await h.node(msgs[0].to), { role: 'follower', term: 1, votedFor: 'n0' });
  const replies = (await h.inFlight()).filter((m) => m.action === 'VoteReply');
  assert.deepEqual(replies[0].data, { term: 1, granted: true });
  assert.equal(replies[0].to, 'n0');
  await h.deliverAll();
  assert.deepEqual(await views(h), [
    { role: 'leader', term: 1, votedFor: 'n0' },
    { role: 'follower', term: 1, votedFor: 'n0' },
    { role: 'follower', term: 1, votedFor: 'n0' },
  ]);
  assert.equal((await h.timeout('n1')).ok, false);
  await h.__dispose();
});

test('all time out: nobody wins, nobody double-votes', async () => {
  const h = await createHost();
  for (const n of ['n0', 'n1', 'n2']) assert.deepEqual(await h.timeout(n), { ok: true });
  await h.deliverAll();
  const v = await views(h);
  assert.equal(v.filter((x: any) => x.role === 'leader').length, 0);
  for (const [i, x] of v.entries()) assert.equal(x.votedFor, `n${i}`);
  await h.__dispose();
});

test('random orders: at most one leader', async () => {
  for (let r = 0; r < 30; r++) {
    const h = await createHost();
    const order = ['n0', 'n1', 'n2'].filter(() => Math.random() < 0.7);
    for (const n of order) {
      await h.timeout(n);
      const f = await h.inFlight();
      if (f.length && Math.random() < 0.5) await h.deliver(f[Math.floor(Math.random() * f.length)].id);
    }
    for (;;) {
      const f = await h.inFlight();
      if (!f.length) break;
      await h.deliver(f[Math.floor(Math.random() * f.length)].id);
    }
    const v = await views(h);
    assert.ok(v.filter((x: any) => x.role === 'leader').length <= 1);
    await h.__dispose();
  }
});

