test('crash and recover: refusals and preserved state', async () => {
  const h = await createHost();
  assert.equal((await h.recover('n0')).ok, false);
  assert.equal((await h.crash('n9')).ok, false);
  assert.deepEqual(await h.crash('n2'), { ok: true });
  assert.equal((await h.crash('n2')).ok, false);
  assert.equal((await h.timeout('n2')).ok, false);
  assert.equal((await h.giveUp('n2')).ok, false);
  assert.deepEqual(await h.node('n2'), { role: 'down', term: 0, votedFor: null, leader: null });
  await h.timeout('n0');
  await h.deliverAll(); // n2 ignores RequestVote and Leader
  assert.deepEqual(await h.node('n2'), { role: 'down', term: 0, votedFor: null, leader: null });
  assert.deepEqual(await h.node('n0'), { role: 'leader', term: 1, votedFor: 'n0', leader: 'n0' });
  assert.deepEqual(await h.recover('n2'), { ok: true });
  assert.deepEqual(await h.node('n2'), { role: 'follower', term: 0, votedFor: null, leader: null });
  // leader crashes and recovers as follower, keeping term, vote and known leader
  await h.crash('n0');
  assert.deepEqual(await h.node('n0'), { role: 'down', term: 1, votedFor: 'n0', leader: 'n0' });
  await h.recover('n0');
  assert.deepEqual(await h.node('n0'), { role: 'follower', term: 1, votedFor: 'n0', leader: 'n0' });
  // n2 can still start an election, but nobody grants it
  assert.deepEqual(await h.timeout('n2'), { ok: true });
  await h.deliverAll();
  const v = await views(h);
  assert.equal(v.filter((x: any) => x.role === 'leader').length, 0);
  assert.equal(v[2].role, 'candidate');
  await h.__dispose();
});

test('crashed candidate recovers as follower and ignores late replies', async () => {
  const h = await createHost();
  await h.timeout('n0');
  await deliverWhere(h, (m) => m.action === 'RequestVote' && m.to === 'n1');
  await h.crash('n0');
  await deliverWhere(h, (m) => m.action === 'VoteReply'); // ignored while down
  await h.recover('n0');
  assert.deepEqual(await h.node('n0'), { role: 'follower', term: 1, votedFor: 'n0', leader: null });
  await h.deliverAll();
  assert.deepEqual(await h.node('n0'), { role: 'follower', term: 1, votedFor: 'n0', leader: null });
  await h.__dispose();
});

