import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../build/host.gen.ts';

const views = async (h: any) => Promise.all(['n0', 'n1', 'n2'].map((n) => h.node(n)));

test('initial state and unknown ids', async () => {
  const h = await createHost();
  assert.deepEqual(await h.node('n0'), { role: 'follower', term: 0, votedFor: null, leader: null });
  assert.equal(await h.node('n9'), null);
  assert.equal((await h.timeout('n9')).ok, false);
  assert.deepEqual(await h.inFlight(), []);
  await h.__dispose();
});

test('single election', async () => {
  const h = await createHost();
  assert.deepEqual(await h.timeout('n0'), { ok: true });
  assert.deepEqual(await h.node('n0'), { role: 'candidate', term: 1, votedFor: 'n0', leader: null });
  const msgs = await h.inFlight();
  assert.equal(msgs.length, 2);
  for (const m of msgs) {
    assert.equal(m.from, 'n0');
    assert.equal(m.action, 'RequestVote');
    assert.deepEqual(m.data, { from: 'n0', term: 1 });
  }
  assert.equal((await h.timeout('n0')).ok, false);
  await h.deliver(msgs[0].id);
  assert.deepEqual(await h.node(msgs[0].to), { role: 'follower', term: 1, votedFor: 'n0', leader: null });
  const replies = (await h.inFlight()).filter((m) => m.action === 'VoteReply');
  assert.deepEqual(replies[0].data, { term: 1, granted: true });
  assert.equal(replies[0].to, 'n0');
  await h.deliverAll();
  assert.deepEqual(await views(h), [
    { role: 'leader', term: 1, votedFor: 'n0', leader: 'n0' },
    { role: 'follower', term: 1, votedFor: 'n0', leader: 'n0' },
    { role: 'follower', term: 1, votedFor: 'n0', leader: 'n0' },
  ]);
  assert.equal((await h.timeout('n1')).ok, false);
  await h.__dispose();
});

const deliverWhere = async (h: any, p: (m: any) => boolean) => {
  const m = (await h.inFlight()).find(p);
  assert.ok(m, 'message expected');
  await h.deliver(m.id);
  return m;
};

test('announce: term-0 node learns leader without voting; candidate steps down', async () => {
  const h = await createHost();
  await h.timeout('n0');
  await h.timeout('n1');
  // n2 votes for n0; n0 wins
  await deliverWhere(h, (m) => m.action === 'RequestVote' && m.from === 'n0' && m.to === 'n2');
  await deliverWhere(h, (m) => m.action === 'VoteReply' && m.to === 'n0');
  assert.deepEqual(await h.node('n0'), { role: 'leader', term: 1, votedFor: 'n0', leader: 'n0' });
  const ann = (await h.inFlight()).filter((m: any) => m.action === 'Leader');
  assert.equal(ann.length, 2);
  for (const m of ann) assert.deepEqual(m.data, { from: 'n0', term: 1 });
  await deliverWhere(h, (m) => m.action === 'Leader' && m.to === 'n1');
  assert.deepEqual(await h.node('n1'), { role: 'follower', term: 1, votedFor: 'n1', leader: 'n0' });
  await h.deliverAll();
  const v = await views(h);
  assert.equal(v.filter((x: any) => x.role === 'leader').length, 1);
  for (const x of v) assert.equal(x.leader, 'n0');
  await h.__dispose();
});

test('Leader to a term-0 node: follower in term 1, no vote', async () => {
  const h = await createHost();
  await h.timeout('n0');
  await deliverWhere(h, (m) => m.action === 'RequestVote' && m.to === 'n1');
  await deliverWhere(h, (m) => m.action === 'VoteReply');
  await deliverWhere(h, (m) => m.action === 'Leader' && m.to === 'n2');
  assert.deepEqual(await h.node('n2'), { role: 'follower', term: 1, votedFor: null, leader: 'n0' });
  await h.__dispose();
});

test('giveUp: candidate becomes follower, keeps self-vote, ignores late replies', async () => {
  const h = await createHost();
  assert.equal((await h.giveUp('n0')).ok, false);
  assert.equal((await h.giveUp('n9')).ok, false);
  await h.timeout('n0');
  assert.deepEqual(await h.giveUp('n0'), { ok: true });
  assert.deepEqual(await h.node('n0'), { role: 'follower', term: 1, votedFor: 'n0', leader: null });
  assert.equal((await h.giveUp('n0')).ok, false);
  assert.equal((await h.timeout('n0')).ok, false);
  await h.deliverAll();
  assert.deepEqual(await h.node('n0'), { role: 'follower', term: 1, votedFor: 'n0', leader: null });
  await h.__dispose();
});

test('giveUp: gave-up node refuses other candidates; another can still win', async () => {
  const h = await createHost();
  await h.timeout('n0');
  await h.giveUp('n0');
  await h.timeout('n1');
  await deliverWhere(h, (m) => m.action === 'RequestVote' && m.from === 'n1' && m.to === 'n0');
  const r = (await h.inFlight()).find((m: any) => m.action === 'VoteReply' && m.to === 'n1');
  assert.deepEqual(r.data, { term: 1, granted: false });
  await h.deliverAll();
  const v = await views(h);
  // n2 got n0's RequestVote or n1's first; either way at most one leader
  assert.ok(v.filter((x: any) => x.role === 'leader').length <= 1);
  assert.equal(v[0].votedFor, 'n0');
  await h.__dispose();
});

test('all time out: nobody wins, nobody double-votes', async () => {
  const h = await createHost();
  for (const n of ['n0', 'n1', 'n2']) assert.deepEqual(await h.timeout(n), { ok: true });
  await h.deliverAll();
  const v = await views(h);
  assert.equal(v.filter((x: any) => x.role === 'leader').length, 0);
  for (const [i, x] of v.entries()) assert.equal(x.votedFor, `n${i}`);
  await h.__dispose();
});

test('random orders: at most one leader', async () => {
  for (let r = 0; r < 30; r++) {
    const h = await createHost();
    const order = ['n0', 'n1', 'n2'].filter(() => Math.random() < 0.7);
    for (const n of order) {
      await h.timeout(n);
      const f = await h.inFlight();
      if (f.length && Math.random() < 0.5) await h.deliver(f[Math.floor(Math.random() * f.length)].id);
    }
    for (;;) {
      const f = await h.inFlight();
      if (!f.length) break;
      await h.deliver(f[Math.floor(Math.random() * f.length)].id);
    }
    const v = await views(h);
    assert.ok(v.filter((x: any) => x.role === 'leader').length <= 1);
    await h.__dispose();
  }
});
